require"active_support/security_utils";require"active_support/messages/rotator";module ActiveSupport;class SecureCompareRotator;include SecurityUtils;InvalidMatch=Class.new(StandardError);def initialize(value,on_rotation:nil)@value=value;@rotate_values=[];@on_rotation=on_rotation;end;def rotate(previous_value)@rotate_values<<previous_value;end;def secure_compare!(other_value,on_rotation:@on_rotation)if secure_compare(@value,other_value);true;elsif @rotate_values.any?{|value|secure_compare(value,other_value)};on_rotation&.call;true;else raise InvalidMatch;end;end;end;end
